-- ============================================================================
-- ISTAPA - Ajout des 6 filières niveau Ingénieur/Licence/Master
-- (supervision académique ISABEE - Université de Bertoua)
-- Diplôme obtenu : Master | Certificats requis : DUT, DTS, HND/BTS, Licence
-- Compatible MariaDB 10.4 / InnoDB / utf8mb4
-- Prérequis : les tables `certificates` et `program_certificates` doivent déjà
-- exister (script istapa_programs_update_v2.sql exécuté au préalable).
-- ============================================================================

SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
START TRANSACTION;
SET time_zone = "+00:00";

-- ----------------------------------------------------------------------------
-- 1) Les 6 nouvelles filières (id auto-incrémenté à partir de 7)
-- ----------------------------------------------------------------------------
INSERT INTO `programs` (`slug`, `cover_image`, `duration_months`, `degree_code`, `degree_name_en`, `degree_name_fr`, `degree_description_en`, `degree_description_fr`, `title_en`, `title_fr`, `short_description_en`, `short_description_fr`, `content_en`, `content_fr`, `is_published`, `sort_order`, `view_count`, `created_at`, `updated_at`) VALUES
('master-production-animale-halieutique', NULL, NULL, 'MASTER', 'Master''s Degree', 'Master', 'An advanced-level track delivered under the academic supervision of ISABEE (University of Bertoua), open to holders of a first higher-education diploma (DUT, DTS, HND/BTS or Bachelor''s), leading to an Engineering, Bachelor''s or Master''s degree depending on the track and duration chosen.', 'Une filière de niveau avancé dispensée sous la supervision académique de l''ISABEE (Université de Bertoua), ouverte aux titulaires d''un premier diplôme de l''enseignement supérieur (DUT, DTS, HND/BTS ou Licence), menant à un diplôme d''Ingénieur, de Licence ou de Master selon la filière et la durée choisies.', 'Animal and Fishery Production', 'Production Animale et Halieutique', 'Advanced scientific training in livestock and fish farming, Engineering/Master level.', 'Approfondissement scientifique en élevage et pisciculture, niveau Ingénieur/Master.', '<h2>Program Overview</h2><p>This advanced track builds on the animal and fisheries sciences covered at BTS/HND level, with a focus on research, value-chain management and innovation, training professionals able to design and manage modern, sustainable livestock and aquaculture production systems.</p><h3>Program Content</h3><ul><li>Advanced zootechnics and fisheries science</li><li>Animal genetics and breeding improvement</li><li>Aquaculture and fish-farming systems management</li><li>Nutrition and industrial-scale feed formulation</li><li>Animal health and farm biosecurity</li><li>Economics and management of livestock value chains</li><li>Agropastoral project design and management</li><li>Research methodology</li></ul><h3>Career Opportunities</h3><p><strong>Public sector:</strong> Ministry of Livestock, Fisheries and Animal Industries (MINEPIA), IRAD, technical and management positions.</p><p><strong>Private sector:</strong> technical management of agropastoral and fish farms, meat, dairy and fisheries agro-industry.</p><p><strong>NGOs and international organizations:</strong> FAO, GIZ, World Bank, IFAD on livestock and food security programs.</p><p><strong>Academia and research:</strong> higher education teaching, applied research and doctoral studies in animal science.</p><h3>Outlook</h3><ul><li>Growing demand for professionals able to modernize livestock and aquaculture value chains.</li><li>Expansion of commercial aquaculture in Cameroon.</li><li>Opportunities in processing and value-addition of animal and fisheries products.</li></ul>', '<h2>Présentation du programme</h2><p>Ce cursus avancé approfondit les sciences animales et halieutiques abordées en BTS/HND, avec une orientation recherche, gestion de filière et innovation, en vue de former des cadres capables de concevoir et piloter des systèmes de production animale et aquacole modernes et durables.</p><h3>Contenu du programme</h3><ul><li>Zootechnie et sciences halieutiques avancées</li><li>Génétique et amélioration animale</li><li>Aquaculture et gestion des systèmes piscicoles</li><li>Nutrition et formulation d''aliments à l''échelle industrielle</li><li>Santé animale et biosécurité des élevages</li><li>Économie et gestion des filières animales</li><li>Montage et gestion de projets agropastoraux</li><li>Méthodologie de la recherche</li></ul><h3>Débouchés professionnels</h3><p><strong>Secteur public:</strong> Ministère de l''Élevage, des Pêches et des Industries Animales (MINEPIA), IRAD, postes de cadre technique et de direction.</p><p><strong>Secteur privé:</strong> direction technique d''exploitations agropastorales et piscicoles, agro-industrie de la viande, du lait et des produits halieutiques.</p><p><strong>ONG et organisations internationales:</strong> FAO, GIZ, Banque mondiale, FIDA sur les programmes d''élevage et de sécurité alimentaire.</p><p><strong>Académie et recherche:</strong> enseignement supérieur, recherche appliquée et poursuite d''études doctorales en sciences animales.</p><h3>Perspectives</h3><ul><li>Demande croissante de cadres capables de moderniser les filières animales et aquacoles.</li><li>Développement de l''aquaculture commerciale au Cameroun.</li><li>Opportunités dans la transformation et la valorisation des produits animaux et halieutiques.</li></ul>', 1, 7, 0, current_timestamp(), current_timestamp()),
('master-production-vegetale', NULL, NULL, 'MASTER', 'Master''s Degree', 'Master', 'An advanced-level track delivered under the academic supervision of ISABEE (University of Bertoua), open to holders of a first higher-education diploma (DUT, DTS, HND/BTS or Bachelor''s), leading to an Engineering, Bachelor''s or Master''s degree depending on the track and duration chosen.', 'Une filière de niveau avancé dispensée sous la supervision académique de l''ISABEE (Université de Bertoua), ouverte aux titulaires d''un premier diplôme de l''enseignement supérieur (DUT, DTS, HND/BTS ou Licence), menant à un diplôme d''Ingénieur, de Licence ou de Master selon la filière et la durée choisies.', 'Crop Production', 'Production Végétale', 'Advanced scientific training in crop production, Engineering/Master level.', 'Approfondissement scientifique en production végétale, niveau Ingénieur/Master.', '<h2>Program Overview</h2><p>This advanced track builds on the agronomic sciences covered at BTS/HND level, with a focus on research, value-chain management and innovation, training professionals able to design and manage high-performing, sustainable crop production systems.</p><h3>Program Content</h3><ul><li>Advanced agronomy and plant physiology</li><li>Plant breeding and biotechnology</li><li>Precision and digital agriculture</li><li>Integrated soil and fertility management</li><li>Agro-industry and crop product processing</li><li>Economics and management of agricultural value chains</li><li>Agricultural project design and management</li><li>Research methodology</li></ul><h3>Career Opportunities</h3><p><strong>Public sector:</strong> Ministry of Agriculture and Rural Development (MINADER), IRAD, technical and management positions.</p><p><strong>Private sector:</strong> technical management of farms, agro-industrial, seed and agrochemical companies.</p><p><strong>NGOs and international organizations:</strong> FAO, GIZ, World Bank, IFAD on agricultural and climate resilience programs.</p><p><strong>Academia and research:</strong> higher education teaching, applied research and doctoral studies in crop science.</p><h3>Outlook</h3><ul><li>Growing demand for professionals able to modernize agricultural value chains.</li><li>Rise of precision agriculture and digital tools (GIS, drones, AI).</li><li>Opportunities in export-oriented and food-security value chains.</li></ul>', '<h2>Présentation du programme</h2><p>Ce cursus avancé approfondit les sciences agronomiques abordées en BTS/HND, avec une orientation recherche, gestion de filière et innovation, en vue de former des cadres capables de concevoir et piloter des systèmes de production végétale performants et durables.</p><h3>Contenu du programme</h3><ul><li>Agronomie et physiologie végétale avancées</li><li>Amélioration des plantes et biotechnologie</li><li>Agriculture de précision et agriculture numérique</li><li>Gestion intégrée des sols et de la fertilité</li><li>Agro-industrie et transformation des produits végétaux</li><li>Économie et gestion des filières agricoles</li><li>Montage et gestion de projets agricoles</li><li>Méthodologie de la recherche</li></ul><h3>Débouchés professionnels</h3><p><strong>Secteur public:</strong> Ministère de l''Agriculture et du Développement Rural (MINADER), IRAD, postes de cadre technique et de direction.</p><p><strong>Secteur privé:</strong> direction technique d''exploitations agricoles, entreprises agro-industrielles, semencières et agrochimiques.</p><p><strong>ONG et organisations internationales:</strong> FAO, GIZ, Banque mondiale, FIDA sur les programmes agricoles et de résilience climatique.</p><p><strong>Académie et recherche:</strong> enseignement supérieur, recherche appliquée et poursuite d''études doctorales en sciences des cultures.</p><h3>Perspectives</h3><ul><li>Demande croissante de cadres capables de moderniser les filières agricoles.</li><li>Essor de l''agriculture de précision et des outils numériques (SIG, drones, IA).</li><li>Opportunités dans les filières d''exportation et de sécurité alimentaire.</li></ul>', 1, 8, 0, current_timestamp(), current_timestamp()),
('master-agro-industrie-alimentaire', NULL, NULL, 'MASTER', 'Master''s Degree', 'Master', 'An advanced-level track delivered under the academic supervision of ISABEE (University of Bertoua), open to holders of a first higher-education diploma (DUT, DTS, HND/BTS or Bachelor''s), leading to an Engineering, Bachelor''s or Master''s degree depending on the track and duration chosen.', 'Une filière de niveau avancé dispensée sous la supervision académique de l''ISABEE (Université de Bertoua), ouverte aux titulaires d''un premier diplôme de l''enseignement supérieur (DUT, DTS, HND/BTS ou Licence), menant à un diplôme d''Ingénieur, de Licence ou de Master selon la filière et la durée choisies.', 'Agro-Food Processing', 'Agro-Industrie Alimentaire', 'Advanced training in food processing and product quality.', 'Formation avancée en transformation agroalimentaire et qualité des produits.', '<h2>Program Overview</h2><p>This track trains professionals able to design, manage and optimize food-processing operations, from raw material to finished product, with a focus on quality, food safety and industrial competitiveness.</p><h3>Program Content</h3><ul><li>Food processing technologies</li><li>Food safety and quality (HACCP)</li><li>Packaging, preservation and conditioning</li><li>Food process engineering</li><li>Food standards and regulation</li><li>Production and supply chain management</li><li>Marketing of agri-food products</li><li>Agro-industrial project design and management</li></ul><h3>Career Opportunities</h3><p><strong>Public sector:</strong> Ministry of Agriculture and Rural Development (MINADER), Ministry of SMEs, quality control and standards bodies.</p><p><strong>Private sector:</strong> food processing units, dairy, milling, brewing and canning industries.</p><p><strong>NGOs and international organizations:</strong> FAO and organizations promoting food security and local value-chain development.</p><p><strong>Entrepreneurship:</strong> founding and managing one''s own food processing business.</p><h3>Outlook</h3><ul><li>Growing demand for locally processed products to reduce imports.</li><li>Development of agro-industry as a driver of added value for Cameroonian agriculture.</li><li>Opportunities in exporting processed products (cocoa, coffee, fruit, dairy).</li></ul>', '<h2>Présentation du programme</h2><p>Cette filière forme des cadres capables de concevoir, gérer et optimiser des unités de transformation agroalimentaire, de la matière première au produit fini, en intégrant qualité, sécurité sanitaire et compétitivité industrielle.</p><h3>Contenu du programme</h3><ul><li>Technologies de transformation agroalimentaire</li><li>Sécurité sanitaire et qualité des aliments (HACCP)</li><li>Emballage, conservation et conditionnement</li><li>Génie des procédés agroalimentaires</li><li>Normes et réglementation agroalimentaire</li><li>Gestion de production et de la chaîne logistique</li><li>Marketing et commercialisation des produits agroalimentaires</li><li>Montage et gestion de projets agro-industriels</li></ul><h3>Débouchés professionnels</h3><p><strong>Secteur public:</strong> Ministère de l''Agriculture et du Développement Rural (MINADER), Ministère des Petites et Moyennes Entreprises, organismes de normalisation et de contrôle qualité.</p><p><strong>Secteur privé:</strong> unités de transformation agroalimentaire, industries laitières, meunières, brassicoles et de conserverie.</p><p><strong>ONG et organisations internationales:</strong> FAO et organisations promouvant la sécurité alimentaire et la valorisation des filières locales.</p><p><strong>Entrepreneuriat:</strong> création et gestion de sa propre unité de transformation agroalimentaire.</p><h3>Perspectives</h3><ul><li>Demande croissante de produits transformés localement pour réduire les importations.</li><li>Développement de l''agro-industrie comme moteur de valeur ajoutée pour l''agriculture camerounaise.</li><li>Opportunités dans l''exportation de produits transformés (cacao, café, fruits, produits laitiers).</li></ul>', 1, 9, 0, current_timestamp(), current_timestamp()),
('master-entrepreneuriat-agropastoral', NULL, NULL, 'MASTER', 'Master''s Degree', 'Master', 'An advanced-level track delivered under the academic supervision of ISABEE (University of Bertoua), open to holders of a first higher-education diploma (DUT, DTS, HND/BTS or Bachelor''s), leading to an Engineering, Bachelor''s or Master''s degree depending on the track and duration chosen.', 'Une filière de niveau avancé dispensée sous la supervision académique de l''ISABEE (Université de Bertoua), ouverte aux titulaires d''un premier diplôme de l''enseignement supérieur (DUT, DTS, HND/BTS ou Licence), menant à un diplôme d''Ingénieur, de Licence ou de Master selon la filière et la durée choisies.', 'Agro-Pastoral Entrepreneurship', 'Entrepreneuriat Agropastoral', 'Advanced training in launching and managing agropastoral businesses.', 'Formation avancée à la création et à la gestion d''entreprises agropastorales.', '<h2>Program Overview</h2><p>This track trains professionals and future entrepreneurs able to design, finance and lead viable agropastoral businesses, combining technical agropastoral knowledge with management, finance and marketing skills.</p><h3>Program Content</h3><ul><li>Agropastoral business management</li><li>Business plan development and project design</li><li>Agricultural financing and microfinance</li><li>Marketing of agropastoral products</li><li>Accounting and financial management</li><li>Agropastoral value chains</li><li>Business law and taxation</li><li>Innovation and digital tools in agribusiness</li></ul><h3>Career Opportunities</h3><p><strong>Entrepreneurship:</strong> founding and leading one''s own agropastoral or agro-industrial business.</p><p><strong>Public sector:</strong> Ministry of Small and Medium-sized Enterprises, Social Economy and Handicrafts, rural entrepreneurship support structures.</p><p><strong>Private sector:</strong> business development consulting, microfinance institutions, agricultural cooperatives.</p><p><strong>NGOs and international organizations:</strong> rural entrepreneurship and financial inclusion programs (GIZ, IFAD, World Bank).</p><h3>Outlook</h3><ul><li>Growth of agribusiness and agri-food startups in Cameroon.</li><li>Increasing access to financing for young agropastoral entrepreneurs.</li><li>Demand for management skills to structure still-informal value chains.</li></ul>', '<h2>Présentation du programme</h2><p>Cette filière forme des cadres et futurs entrepreneurs capables de concevoir, financer et diriger des entreprises agropastorales viables, en combinant compétences techniques agro-pastorales et compétences de gestion, de finance et de commercialisation.</p><h3>Contenu du programme</h3><ul><li>Gestion d''entreprise agropastorale</li><li>Business plan et montage de projets</li><li>Financement et microfinance agricole</li><li>Marketing et commercialisation des produits agropastoraux</li><li>Comptabilité et gestion financière</li><li>Chaînes de valeur agropastorales</li><li>Droit des affaires et fiscalité</li><li>Innovation et numérique en agrobusiness</li></ul><h3>Débouchés professionnels</h3><p><strong>Entrepreneuriat:</strong> création et direction de sa propre entreprise agropastorale ou agro-industrielle.</p><p><strong>Secteur public:</strong> Ministère des Petites et Moyennes Entreprises, de l''Économie Sociale et de l''Artisanat, structures d''appui à l''entrepreneuriat rural.</p><p><strong>Secteur privé:</strong> conseil en développement d''entreprise, institutions de microfinance, coopératives agricoles.</p><p><strong>ONG et organisations internationales:</strong> programmes d''appui à l''entrepreneuriat rural et à l''inclusion financière (GIZ, FIDA, Banque mondiale).</p><h3>Perspectives</h3><ul><li>Essor de l''agrobusiness et des start-ups agroalimentaires au Cameroun.</li><li>Accès croissant au financement pour les jeunes entrepreneurs agropastoraux.</li><li>Demande de compétences en gestion pour structurer des filières encore informelles.</li></ul>', 1, 10, 0, current_timestamp(), current_timestamp()),
('master-gestion-environnementale', NULL, NULL, 'MASTER', 'Master''s Degree', 'Master', 'An advanced-level track delivered under the academic supervision of ISABEE (University of Bertoua), open to holders of a first higher-education diploma (DUT, DTS, HND/BTS or Bachelor''s), leading to an Engineering, Bachelor''s or Master''s degree depending on the track and duration chosen.', 'Une filière de niveau avancé dispensée sous la supervision académique de l''ISABEE (Université de Bertoua), ouverte aux titulaires d''un premier diplôme de l''enseignement supérieur (DUT, DTS, HND/BTS ou Licence), menant à un diplôme d''Ingénieur, de Licence ou de Master selon la filière et la durée choisies.', 'Environmental Management', 'Gestion Environnementale', 'Advanced training in environmental management and climate governance.', 'Approfondissement en gestion environnementale et gouvernance climatique.', '<h2>Program Overview</h2><p>This advanced track builds on the environmental management covered at BTS/HND level, with a focus on research, public policy and governance, training professionals able to lead complex environmental and climate strategies.</p><h3>Program Content</h3><ul><li>Environmental governance and public policy</li><li>Advanced environmental and social impact assessment</li><li>Environmental economics and climate finance</li><li>Climate risk management and adaptation</li><li>Advanced GIS and remote sensing</li><li>Circular economy and waste management</li><li>Environmental project design and management</li><li>Research methodology</li></ul><h3>Career Opportunities</h3><p><strong>Public sector:</strong> Ministry of Environment, Nature Protection and Sustainable Development (MINEPDED), management positions.</p><p><strong>Private sector:</strong> leadership of environmental consulting firms, corporate sustainability departments.</p><p><strong>NGOs and international organizations:</strong> WWF, UNDP, GIZ, FAO, World Bank on conservation and climate resilience.</p><p><strong>Academia and research:</strong> higher education teaching, research and doctoral studies in environmental science.</p><h3>Outlook</h3><ul><li>Strengthening of national and international climate policies.</li><li>Growing demand for professionals in environmental governance and climate finance.</li><li>Development of carbon markets and the circular economy.</li></ul>', '<h2>Présentation du programme</h2><p>Ce cursus avancé approfondit la gestion environnementale abordée en BTS/HND, avec une orientation recherche, politique publique et gouvernance, en vue de former des cadres capables de piloter des stratégies environnementales et climatiques complexes.</p><h3>Contenu du programme</h3><ul><li>Gouvernance environnementale et politiques publiques</li><li>Évaluation environnementale et sociale approfondie</li><li>Économie de l''environnement et finance climatique</li><li>Gestion des risques climatiques et adaptation</li><li>SIG avancé et télédétection</li><li>Économie circulaire et gestion des déchets</li><li>Montage et gestion de projets environnementaux</li><li>Méthodologie de la recherche</li></ul><h3>Débouchés professionnels</h3><p><strong>Secteur public:</strong> Ministère de l''Environnement, de la Protection de la Nature et du Développement Durable (MINEPDED), postes de cadre et de direction.</p><p><strong>Secteur privé:</strong> direction de bureaux d''études environnementales, départements de durabilité d''entreprise.</p><p><strong>ONG et organisations internationales:</strong> WWF, PNUD, GIZ, FAO, Banque mondiale sur la conservation et la résilience climatique.</p><p><strong>Académie et recherche:</strong> enseignement supérieur, recherche et poursuite d''études doctorales en sciences de l''environnement.</p><h3>Perspectives</h3><ul><li>Renforcement des politiques climatiques nationales et internationales.</li><li>Demande croissante de cadres en gouvernance environnementale et finance climatique.</li><li>Développement des marchés du carbone et de l''économie circulaire.</li></ul>', 1, 11, 0, current_timestamp(), current_timestamp()),
('master-energies-renouvelables', NULL, NULL, 'MASTER', 'Master''s Degree', 'Master', 'An advanced-level track delivered under the academic supervision of ISABEE (University of Bertoua), open to holders of a first higher-education diploma (DUT, DTS, HND/BTS or Bachelor''s), leading to an Engineering, Bachelor''s or Master''s degree depending on the track and duration chosen.', 'Une filière de niveau avancé dispensée sous la supervision académique de l''ISABEE (Université de Bertoua), ouverte aux titulaires d''un premier diplôme de l''enseignement supérieur (DUT, DTS, HND/BTS ou Licence), menant à un diplôme d''Ingénieur, de Licence ou de Master selon la filière et la durée choisies.', 'Renewable Energy', 'Énergies Renouvelables', 'Advanced training in renewable energy engineering and project management.', 'Approfondissement en ingénierie et gestion de projets énergétiques renouvelables.', '<h2>Program Overview</h2><p>This advanced track builds on the renewable energy technologies covered at BTS/HND level, with a focus on engineering, project management and energy policy, training professionals able to design and lead sustainable electrification projects.</p><h3>Program Content</h3><ul><li>Advanced photovoltaic systems engineering</li><li>Smart grids and mini-grids</li><li>Industrial-scale hydropower and bioenergy</li><li>Energy economics and policy</li><li>Energy project management and financing</li><li>Industrial energy efficiency</li><li>Energy law and regulation</li><li>Research methodology</li></ul><h3>Career Opportunities</h3><p><strong>Public sector:</strong> Ministry of Water Resources and Energy (MINEE), SONATREL, AER, engineering and management positions.</p><p><strong>Private sector:</strong> technical leadership of solar and energy projects, sustainable infrastructure engineering firms.</p><p><strong>NGOs and international organizations:</strong> UNDP, GIZ, World Bank, WWF on sustainable electrification projects.</p><p><strong>Academia and research:</strong> higher education teaching, research and doctoral studies in renewable energy.</p><h3>Outlook</h3><ul><li>National target of 25% renewable energy share by 2035.</li><li>Development of solar mini-grids and hydropower modernization.</li><li>Regional demand for engineers skilled in sustainable energy.</li></ul>', '<h2>Présentation du programme</h2><p>Ce cursus avancé approfondit les technologies des énergies renouvelables abordées en BTS/HND, avec une orientation ingénierie, gestion de projets et politique énergétique, en vue de former des cadres capables de concevoir et piloter des projets d''électrification durable.</p><h3>Contenu du programme</h3><ul><li>Ingénierie avancée des systèmes photovoltaïques</li><li>Réseaux électriques intelligents et mini-réseaux</li><li>Hydroélectricité et bioénergie à l''échelle industrielle</li><li>Économie et politique de l''énergie</li><li>Gestion de projets énergétiques et financement</li><li>Efficacité énergétique industrielle</li><li>Droit et réglementation de l''énergie</li><li>Méthodologie de la recherche</li></ul><h3>Débouchés professionnels</h3><p><strong>Secteur public:</strong> Ministère de l''Eau et de l''Énergie (MINEE), SONATREL, AER, postes d''ingénieur et de cadre.</p><p><strong>Secteur privé:</strong> direction technique de projets solaires et énergétiques, bureaux d''ingénierie en infrastructures durables.</p><p><strong>ONG et organisations internationales:</strong> PNUD, GIZ, Banque mondiale, WWF sur les projets d''électrification durable.</p><p><strong>Académie et recherche:</strong> enseignement supérieur, recherche et poursuite d''études doctorales en énergies renouvelables.</p><h3>Perspectives</h3><ul><li>Objectif national de 25 % d''énergie renouvelable d''ici 2035.</li><li>Développement des mini-réseaux solaires et de la modernisation hydroélectrique.</li><li>Demande régionale d''ingénieurs qualifiés en énergies durables.</li></ul>', 1, 12, 0, current_timestamp(), current_timestamp());

-- ----------------------------------------------------------------------------
-- 2) Certificats requis pour s'inscrire : DUT, DTS, HND/BTS ou Licence
--    (les 6 filières ci-dessus viennent d'être insérées avec sort_order 7 à 12)
-- ----------------------------------------------------------------------------
INSERT INTO `program_certificates` (`program_id`, `certificate_id`)
SELECT p.id, c.id
FROM `programs` p
JOIN `certificates` c ON c.code IN ('DUT','DTS','HND_BTS','BACHELOR')
WHERE p.sort_order BETWEEN 7 AND 12;

COMMIT;
